cd /private/tmp/claude-501/-Users-guygouri-Devlab-ernlang-ern/c986905c-e900-4fd9-bebc-4a3ce7ebb180/scratchpad/rev7/report && cat > py/defs.py <<'EOF'
import re,sys
def defs(path):
    L=open(path).read().split('\n'); out={}; i=0
    while i<len(L):
        m=re.match(r'^(?:@\[[^\]]*\]\s*)?(?:private |protected )?(def|structure|inductive|abbrev|instance)\s+(\S+)',L[i])
        if m:
            name=m.group(2); j=i+1; buf=[L[i]]
            while j<len(L) and not re.match(r'^(/--|theorem |def |structure |inductive |abbrev |instance |example|/-!|section|end |namespace|@\[)',L[j]):
                buf.append(L[j]); j+=1
            out[name]=' '.join(' '.join(buf).split()); i=j; continue
        i+=1
    return out
a=defs(sys.argv[1]); b=defs(sys.argv[2])
for k in a:
    if k not in b: print('GONE',k)
    elif a[k]!=b[k]: print('CHANGED',k)
for k in b:
    if k not in a: print('NEW',k)
EOF
python3 -I py/defs.py ../../p3/p2.lean /Users/guygouri/Devlab/ernlang/ern/formal/Ern/MM03.lean

